func zjFoldFieldName_ObservedPayload(name string) string {
	var lower [6]byte
	for i := 0; i < len(name); i++ {
		c := name[i]
		if c >= 0x80 {
			goto zjUnicode
		}
		if i < len(lower) {
			if 'A' <= c && c <= 'Z' {
				c += 'a' - 'A'
			}
			lower[i] = c
		}
	}
	if len(name) > len(lower) {
		return name
	}
	switch string(lower[:len(name)]) {
	case "values":
		return "Values"
	}
	return name
zjUnicode:
	if strings_.EqualFold(name, "Values") {
		return "Values"
	}
	return name
}

